// ================== ROUTER DE MODELOS (NVIDIA + OLLAMA) ==================
// Elige el LLM según la especialidad del agente, la complejidad de la tarea
// y el uso registrado. Si un modelo falla o se agota, "Registrar fallo" lo
// marca y vuelve acá para probar el siguiente de la lista.
//
// - Agente general con tarea "simple": primero modelos locales de Ollama, después NVIDIA.
// - Resto: primero NVIDIA, después Ollama como último respaldo.
// - NVIDIA da ~40 requests/minuto POR CUENTA (compartido entre modelos).
// - rpm / rpd por modelo son límites "blandos" propios, editables.
// IDs: "nvidia/..." van por la API de NVIDIA; "ollama/<modelo>" por Ollama local.

const CONFIG = {
  globalRpmNvidia: 36,    // margen bajo el límite de 40 RPM de la cuenta NVIDIA
  maxIntentos: 8,         // modelos distintos a probar por pedido
  maxEsperaSeg: 60,       // espera máxima si todos están en cooldown
  maxEsperas: 3,
  models: {
    'mistralai/mistral-large-4-1t-a52b':       { rpm: 12, rpd: 1500 },
    'nvidia/nemotron-3-ultra-550b-a55b':       { rpm: 12, rpd: 1500 },
    'z-ai/glm-5.3-flash':                      { rpm: 15, rpd: 2000 },
    'deepseek-ai/deepseek-v4.1-flash':         { rpm: 15, rpd: 2000 },
    'minimaxai/minimax-m3.1-flash':            { rpm: 15, rpd: 2000 },
    'stepfun-ai/step-5-preview':               { rpm: 10, rpd: 1000 },
    'poolside/laguna-xs-2.1':                  { rpm: 15, rpd: 2000 },
    'nvidia/nemotron-3.5-super-vl-120b-a12b':  { rpm: 12, rpd: 1500 },
    'nvidia/nemotron-3-nano-omni-30b-a3b-reasoning': { rpm: 20, rpd: 3000 },
    'nvidia/nemotron-3.5-lightning-30b-a3b':   { rpm: 25, rpd: 5000 },
    'nvidia/nemotron-3.5-bolt-e4b':            { rpm: 30, rpd: 5000 },
    'meta/muse-glimmer-30b':                   { rpm: 20, rpd: 3000 },
    'google/gemma-4-31b-it':                   { rpm: 20, rpd: 3000 },
    'openai/gpt-oss-20b':                      { rpm: 25, rpd: 5000 },
    // Ollama local: sin cuota, el límite real es tu GPU (OLLAMA_NUM_PARALLEL)
    'ollama/nemotron-3.5-bolt:e4b':            { rpm: 30 },
    'ollama/nemotron-3-nano:4b':               { rpm: 30 },
    'ollama/qwen3:14b':                        { rpm: 30 },
    'ollama/gemma4:12b':                       { rpm: 30 },
  },
  // Orden de preferencia NVIDIA por especialidad (el primero es el ideal).
  // Medido 30/10/2026: mistral-large-4 es lento (~20s+ razonando); glm-5.3, gemma-4,
  // laguna y nano-omni tardaron >45s, por eso quedan como respaldo.
  agents: {
    orquestador:              ['nvidia/nemotron-3-ultra-550b-a55b', 'deepseek-ai/deepseek-v4.1-flash', 'minimaxai/minimax-m3.1-flash', 'mistralai/mistral-large-4-1t-a52b'],
    general:                  ['nvidia/nemotron-3.5-lightning-30b-a3b', 'deepseek-ai/deepseek-v4.1-flash', 'nvidia/nemotron-3-ultra-550b-a55b', 'openai/gpt-oss-20b'],
    // Revisión final: modelos rápidos primero (ultra tardó >100 s en revisar, 30/10/2026)
    verificador:              ['nvidia/nemotron-3.5-lightning-30b-a3b', 'deepseek-ai/deepseek-v4.1-flash', 'minimaxai/minimax-m3.1-flash', 'nvidia/nemotron-3-ultra-550b-a55b'],
    sintesis:                 ['nvidia/nemotron-3-ultra-550b-a55b', 'deepseek-ai/deepseek-v4.1-flash', 'mistralai/mistral-large-4-1t-a52b', 'nvidia/nemotron-3.5-lightning-30b-a3b'],
    // Gráficos e imágenes: modelos rápidos y buenos armando JSON
    visualizacion:            ['nvidia/nemotron-3.5-lightning-30b-a3b', 'deepseek-ai/deepseek-v4.1-flash', 'minimaxai/minimax-m3.1-flash', 'nvidia/nemotron-3-ultra-550b-a55b'],
    agentic_ai:               ['nvidia/nemotron-3-ultra-550b-a55b', 'minimaxai/minimax-m3.1-flash', 'deepseek-ai/deepseek-v4.1-flash', 'nvidia/nemotron-3.5-lightning-30b-a3b'],
    fisica_robotica:          ['nvidia/nemotron-3-ultra-550b-a55b', 'nvidia/nemotron-3.5-super-vl-120b-a12b', 'deepseek-ai/deepseek-v4.1-flash', 'nvidia/nemotron-3-nano-omni-30b-a3b-reasoning'],
    vision:                   ['nvidia/nemotron-3.5-super-vl-120b-a12b', 'meta/muse-glimmer-30b', 'z-ai/glm-5.3-flash', 'nvidia/nemotron-3-nano-omni-30b-a3b-reasoning'],
    entrenamiento_inferencia: ['deepseek-ai/deepseek-v4.1-flash', 'nvidia/nemotron-3-ultra-550b-a55b', 'stepfun-ai/step-5-preview', 'mistralai/mistral-large-4-1t-a52b'],
    datos_optimizacion:       ['openai/gpt-oss-20b', 'deepseek-ai/deepseek-v4.1-flash', 'nvidia/nemotron-3-ultra-550b-a55b', 'mistralai/mistral-large-4-1t-a52b'],
    gpu_dev:                  ['stepfun-ai/step-5-preview', 'minimaxai/minimax-m3.1-flash', 'deepseek-ai/deepseek-v4.1-flash', 'poolside/laguna-xs-2.1'],
    infra_redes:              ['minimaxai/minimax-m3.1-flash', 'nvidia/nemotron-3-ultra-550b-a55b', 'deepseek-ai/deepseek-v4.1-flash', 'poolside/laguna-xs-2.1'],
    salud_ciencias:           ['nvidia/nemotron-3-ultra-550b-a55b', 'mistralai/mistral-large-4-1t-a52b', 'deepseek-ai/deepseek-v4.1-flash', 'google/gemma-4-31b-it'],
  },
  // Modelos locales por especialidad (todos soportan tool calling). Instalados (31/10/2026):
  // nemotron-3.5-bolt:e4b (7,9 GB) y nemotron-3-nano:4b (2,8 GB) entran juntos en la GPU de 12 GB y se alternan
  // por "slot"; qwen3:14b (9,3 GB) es el de mejor calidad para razonar y código; gemma4:12b (8 GB) entiende imágenes.
  ollama: {
    default:     ['ollama/nemotron-3.5-bolt:e4b', 'ollama/nemotron-3-nano:4b', 'ollama/qwen3:14b', 'ollama/gemma4:12b'],
    gpu_dev:     ['ollama/qwen3:14b', 'ollama/gemma4:12b'],
    infra_redes: ['ollama/qwen3:14b', 'ollama/gemma4:12b'],
    vision:      ['ollama/gemma4:12b', 'ollama/nemotron-3.5-bolt:e4b', 'ollama/qwen3:14b'],
  },
  // Si se agota toda la lista del agente, sigue con estos
  fallbackGeneral: [
    'nvidia/nemotron-3-ultra-550b-a55b', 'deepseek-ai/deepseek-v4.1-flash', 'minimaxai/minimax-m3.1-flash',
    'nvidia/nemotron-3.5-super-vl-120b-a12b', 'openai/gpt-oss-20b', 'nvidia/nemotron-3.5-lightning-30b-a3b',
    'nvidia/nemotron-3.5-bolt-e4b', 'mistralai/mistral-large-4-1t-a52b', 'z-ai/glm-5.3-flash', 'google/gemma-4-31b-it',
  ],
};

// La configuración (CONFIG) está en config_modelos.js; gen.py la antepone a este código.
const isOllama = m => m.startsWith('ollama/');
// Estado compartido (usos, pausas) en mcp-tools: el "static data" de n8n se pisa entre ejecuciones en paralelo
const ROUTER = $env.MCP_URL.replace(/\/mcp\/?$/, '') + '/router';
const router = (ruta, body) => this.helpers.httpRequest({ method: 'POST', url: `${ROUTER}/${ruta}`, json: true, timeout: 5000,
  headers: { 'X-API-Key': $env.MCP_API_KEY }, body });

const j = { ...$input.item.json };
delete j.action; delete j.waitSeconds; delete j.model; delete j.modelName; delete j.provider;
const r = j._router || { tried: [], errors: [], waits: 0 };

// Aviso de progreso a la web (solo si el pedido viene de un chat de la web local)
const corto = m => String(m || '').replace(/^(ollama|nvidia)\//, '').replace(/^[\w-]+\/(?=[^/]+$)/, '');
const avisar = (tipo, texto, extra = {}) => j.session_id
  ? this.helpers.httpRequest({ method: 'POST', url: $env.WEB_EVENTOS_URL, json: true, timeout: 2000,
      headers: { 'X-API-Key': $env.WEB_EVENTOS_TOKEN },
      body: { chat: j.session_id, tipo, texto, agente: j.agent, ...extra } }).catch(() => null)
  : null;

const nvidia = [...(CONFIG.agents[j.agent] || []), ...CONFIG.fallbackGeneral];
const local = [...(CONFIG.ollama[j.agent] || CONFIG.ollama.default), ...CONFIG.ollama.default];
// Los especialistas llevan el catálogo de skills en el prompt (miles de tokens):
// van a NVIDIA aunque la tarea sea simple, así Ollama queda libre para el agente general.
const localPrimero = j.agent === 'general' && j.complejidad === 'simple';
// Subtareas paralelas (slot impar) arrancan por el segundo modelo local, así no hacen cola en el mismo
if (localPrimero && Number(j.slot) % 2 === 1) local.splice(0, 2, local[1], local[0]);
const order = [...new Set(localPrimero ? [...local, ...nvidia] : [...nvidia, ...local])];

// mcp-tools elige el primer modelo con cupo y registra el uso en el mismo paso (atómico entre agentes en paralelo)
let res = { accion: 'ninguno', espera_ms: null };
if (r.tried.length < CONFIG.maxIntentos) {
  try {
    res = await router('reservar', { orden: order, intentados: r.tried, limites: CONFIG.models, global_rpm: CONFIG.globalRpmNvidia });
  } catch (e) {
    // Sin mcp-tools no hay registro de cupos: se sigue con el primer modelo no probado
    const m = order.find(m => !r.tried.includes(m));
    res = m ? { accion: 'llamar', modelo: m } : res;
  }
}
const chosen = res.accion === 'llamar' ? res.modelo : null;

// Límite global de la cuenta NVIDIA: esperar a que se libere la ventana de 1 minuto
if (res.accion === 'esperar') {
  const waitSeconds = Math.ceil(res.espera_ms / 1000) + 1;
  await avisar('espera', `Esperando cupo de la cuenta NVIDIA (${waitSeconds} s)`);
  return { json: { ...j, _router: { ...r, waits: r.waits + 1 }, action: 'esperar', waitSeconds, motivo: res.motivo } };
}

if (!chosen) {
  const waitSeconds = Math.ceil((res.espera_ms ?? Infinity) / 1000) + 1;
  if (isFinite(waitSeconds) && waitSeconds <= CONFIG.maxEsperaSeg && r.waits < CONFIG.maxEsperas && r.tried.length < CONFIG.maxIntentos) {
    await avisar('espera', `Modelos ocupados o en pausa: esperando ${waitSeconds} s`);
    return { json: { ...j, _router: { ...r, waits: r.waits + 1 }, action: 'esperar', waitSeconds, motivo: 'modelos_en_cooldown' } };
  }
  await avisar('error', `Sin modelos disponibles para ${j.agent}`);
  return { json: { ...j, _router: r, action: 'agotado' } };
}

const que = j.agent === 'orquestador' ? 'Planificando el pedido' : j.agent === 'sintesis' ? 'Integrando las respuestas'
  : j.agent === 'verificador' ? 'Revisando que la respuesta cumpla todo lo pedido'
  : j.fase === 'correccion' ? `${j.agent}: completando lo que faltó` : `${j.agent}: trabajando`;
await avisar('modelo', `${que} con ${corto(chosen)}${r.tried.length ? ' (reintento)' : ''}`,
  { modelo: chosen, proveedor: isOllama(chosen) ? 'ollama' : 'nvidia' });

return {
  json: {
    ...j,
    model: chosen,
    provider: isOllama(chosen) ? 'ollama' : 'nvidia',
    modelName: isOllama(chosen) ? chosen.slice('ollama/'.length) : chosen,
    _router: r,
    action: 'llamar',
  },
};

// ================== ROUTER DE MODELOS (NVIDIA + OLLAMA) ==================
// Elige el LLM según la especialidad del agente, la complejidad de la tarea
// y el uso registrado. Si un modelo falla o se agota, "Registrar fallo" lo
// marca y vuelve acá para probar el siguiente de la lista.
//
// - Agente general con tarea "simple": primero modelos locales de Ollama, después NVIDIA.
// - Resto: primero NVIDIA, después Ollama como último respaldo.
// - NVIDIA da ~40 requests/minuto POR CUENTA (compartido entre modelos).
// - rpm / rpd por modelo son límites "blandos" propios, editables.
// IDs: "nvidia/..." van por la API de NVIDIA; "ollama/<modelo>" por Ollama local.

const CONFIG = {
  globalRpmNvidia: 36,    // margen bajo el límite de 40 RPM de la cuenta NVIDIA
  maxIntentos: 8,         // modelos distintos a probar por pedido
  maxEsperaSeg: 60,       // espera máxima si todos están en cooldown
  maxEsperas: 3,
  models: {
    'mistralai/mistral-large-4-1t-a52b':       { rpm: 12, rpd: 1500 },
    'nvidia/nemotron-3-ultra-550b-a55b':       { rpm: 12, rpd: 1500 },
    'z-ai/glm-5.3-flash':                      { rpm: 15, rpd: 2000 },
    'deepseek-ai/deepseek-v4.1-flash':         { rpm: 15, rpd: 2000 },
    'minimaxai/minimax-m3.1-flash':            { rpm: 15, rpd: 2000 },
    'stepfun-ai/step-5-preview':               { rpm: 10, rpd: 1000 },
    'poolside/laguna-xs-2.1':                  { rpm: 15, rpd: 2000 },
    'nvidia/nemotron-3.5-super-vl-120b-a12b':  { rpm: 12, rpd: 1500 },
    'nvidia/nemotron-3-nano-omni-30b-a3b-reasoning': { rpm: 20, rpd: 3000 },
    'nvidia/nemotron-3.5-lightning-30b-a3b':   { rpm: 25, rpd: 5000 },
    'nvidia/nemotron-3.5-bolt-e4b':            { rpm: 30, rpd: 5000 },
    'meta/muse-glimmer-30b':                   { rpm: 20, rpd: 3000 },
    'google/gemma-4-31b-it':                   { rpm: 20, rpd: 3000 },
    'openai/gpt-oss-20b':                      { rpm: 25, rpd: 5000 },
    // Ollama local: sin cuota, el límite real es tu GPU (OLLAMA_NUM_PARALLEL)
    'ollama/nemotron-3.5-bolt:e4b':            { rpm: 30 },
    'ollama/nemotron-3-nano:4b':               { rpm: 30 },
    'ollama/qwen3:14b':                        { rpm: 30 },
    'ollama/gemma4:12b':                       { rpm: 30 },
  },
  // Orden de preferencia NVIDIA por especialidad (el primero es el ideal).
  // Medido 30/10/2026: mistral-large-4 es lento (~20s+ razonando); glm-5.3, gemma-4,
  // laguna y nano-omni tardaron >45s, por eso quedan como respaldo.
  agents: {
    orquestador:              ['nvidia/nemotron-3-ultra-550b-a55b', 'deepseek-ai/deepseek-v4.1-flash', 'minimaxai/minimax-m3.1-flash', 'mistralai/mistral-large-4-1t-a52b'],
    general:                  ['nvidia/nemotron-3.5-lightning-30b-a3b', 'deepseek-ai/deepseek-v4.1-flash', 'nvidia/nemotron-3-ultra-550b-a55b', 'openai/gpt-oss-20b'],
    // Revisión final: modelos rápidos primero (ultra tardó >100 s en revisar, 30/10/2026)
    verificador:              ['nvidia/nemotron-3.5-lightning-30b-a3b', 'deepseek-ai/deepseek-v4.1-flash', 'minimaxai/minimax-m3.1-flash', 'nvidia/nemotron-3-ultra-550b-a55b'],
    sintesis:                 ['nvidia/nemotron-3-ultra-550b-a55b', 'deepseek-ai/deepseek-v4.1-flash', 'mistralai/mistral-large-4-1t-a52b', 'nvidia/nemotron-3.5-lightning-30b-a3b'],
    // Gráficos e imágenes: modelos rápidos y buenos armando JSON
    visualizacion:            ['nvidia/nemotron-3.5-lightning-30b-a3b', 'deepseek-ai/deepseek-v4.1-flash', 'minimaxai/minimax-m3.1-flash', 'nvidia/nemotron-3-ultra-550b-a55b'],
    agentic_ai:               ['nvidia/nemotron-3-ultra-550b-a55b', 'minimaxai/minimax-m3.1-flash', 'deepseek-ai/deepseek-v4.1-flash', 'nvidia/nemotron-3.5-lightning-30b-a3b'],
    fisica_robotica:          ['nvidia/nemotron-3-ultra-550b-a55b', 'nvidia/nemotron-3.5-super-vl-120b-a12b', 'deepseek-ai/deepseek-v4.1-flash', 'nvidia/nemotron-3-nano-omni-30b-a3b-reasoning'],
    vision:                   ['nvidia/nemotron-3.5-super-vl-120b-a12b', 'meta/muse-glimmer-30b', 'z-ai/glm-5.3-flash', 'nvidia/nemotron-3-nano-omni-30b-a3b-reasoning'],
    entrenamiento_inferencia: ['deepseek-ai/deepseek-v4.1-flash', 'nvidia/nemotron-3-ultra-550b-a55b', 'stepfun-ai/step-5-preview', 'mistralai/mistral-large-4-1t-a52b'],
    datos_optimizacion:       ['openai/gpt-oss-20b', 'deepseek-ai/deepseek-v4.1-flash', 'nvidia/nemotron-3-ultra-550b-a55b', 'mistralai/mistral-large-4-1t-a52b'],
    gpu_dev:                  ['stepfun-ai/step-5-preview', 'minimaxai/minimax-m3.1-flash', 'deepseek-ai/deepseek-v4.1-flash', 'poolside/laguna-xs-2.1'],
    infra_redes:              ['minimaxai/minimax-m3.1-flash', 'nvidia/nemotron-3-ultra-550b-a55b', 'deepseek-ai/deepseek-v4.1-flash', 'poolside/laguna-xs-2.1'],
    salud_ciencias:           ['nvidia/nemotron-3-ultra-550b-a55b', 'mistralai/mistral-large-4-1t-a52b', 'deepseek-ai/deepseek-v4.1-flash', 'google/gemma-4-31b-it'],
  },
  // Modelos locales por especialidad (todos soportan tool calling). Instalados (31/10/2026):
  // nemotron-3.5-bolt:e4b (7,9 GB) y nemotron-3-nano:4b (2,8 GB) entran juntos en la GPU de 12 GB y se alternan
  // por "slot"; qwen3:14b (9,3 GB) es el de mejor calidad para razonar y código; gemma4:12b (8 GB) entiende imágenes.
  ollama: {
    default:     ['ollama/nemotron-3.5-bolt:e4b', 'ollama/nemotron-3-nano:4b', 'ollama/qwen3:14b', 'ollama/gemma4:12b'],
    gpu_dev:     ['ollama/qwen3:14b', 'ollama/gemma4:12b'],
    infra_redes: ['ollama/qwen3:14b', 'ollama/gemma4:12b'],
    vision:      ['ollama/gemma4:12b', 'ollama/nemotron-3.5-bolt:e4b', 'ollama/qwen3:14b'],
  },
  // Si se agota toda la lista del agente, sigue con estos
  fallbackGeneral: [
    'nvidia/nemotron-3-ultra-550b-a55b', 'deepseek-ai/deepseek-v4.1-flash', 'minimaxai/minimax-m3.1-flash',
    'nvidia/nemotron-3.5-super-vl-120b-a12b', 'openai/gpt-oss-20b', 'nvidia/nemotron-3.5-lightning-30b-a3b',
    'nvidia/nemotron-3.5-bolt-e4b', 'mistralai/mistral-large-4-1t-a52b', 'z-ai/glm-5.3-flash', 'google/gemma-4-31b-it',
  ],
};

// Devuelve la configuración del router y el uso registrado de cada modelo (lo consulta la web local)
const h = $input.first().json.headers || {};
if ((h['x-api-key'] || '') !== $env.N8N_WEBHOOK_TOKEN) throw new Error('No autorizado: falta o es incorrecto el header X-API-Key');
// Uso registrado: vive en mcp-tools (compartido entre los agentes en paralelo)
const st = await this.helpers.httpRequest({ method: 'GET', url: $env.MCP_URL.replace(/\/mcp\/?$/, '') + '/router/estado', json: true,
  timeout: 5000, headers: { 'X-API-Key': $env.MCP_API_KEY } }).catch(() => ({}));
const ahora = Date.now();
const hoy = new Date().toISOString().slice(0, 10);
const usados = (st.global || []).filter(t => ahora - t < 60000).length;
const agentesDe = m => Object.entries(CONFIG.agents).filter(([, l]) => l.includes(m)).map(([a]) => a)
  .concat(Object.entries(CONFIG.ollama).filter(([, l]) => l.includes(m)).map(([a]) => a === 'default' ? 'general (local)' : `${a} (local)`));
const modelos = Object.entries(CONFIG.models).map(([id, lim]) => {
  const s = (st.models || {})[id] || {};
  const minuto = (s.minute || []).filter(t => ahora - t < 60000).length;
  const dia = s.day && s.day.date === hoy ? s.day.count : 0;
  const cooldown = s.cooldownUntil && s.cooldownUntil > ahora ? new Date(s.cooldownUntil).toISOString() : null;
  const estado = cooldown ? 'pausa' : lim.rpd && dia >= lim.rpd ? 'agotado' : lim.rpm && minuto >= lim.rpm ? 'limite' : 'disponible';
  return {
    id, proveedor: id.startsWith('ollama/') ? 'ollama' : 'nvidia', rpm: lim.rpm || null, rpd: lim.rpd || null,
    usos_minuto: minuto, usos_hoy: dia, estado, cooldown_hasta: cooldown,
    ultimo_uso: s.lastUsed || null, ultimo_error: s.lastError || null, agentes: agentesDe(id),
    en_fallback: CONFIG.fallbackGeneral.includes(id),
  };
});
return [{ json: { generado: new Date().toISOString(), nvidia_rpm_global: { usados, limite: CONFIG.globalRpmNvidia }, modelos } }];

const prev = $('Elegir modelo').item.json;

// Aviso de progreso a la web (solo si el pedido viene de un chat de la web local)
const corto = m => String(m || '').replace(/^(ollama|nvidia)\//, '').replace(/^[\w-]+\/(?=[^/]+$)/, '');
const avisar = (tipo, texto, extra = {}) => prev.session_id
  ? this.helpers.httpRequest({ method: 'POST', url: $env.WEB_EVENTOS_URL, json: true, timeout: 2000,
      headers: { 'X-API-Key': $env.WEB_EVENTOS_TOKEN },
      body: { chat: prev.session_id, tipo, texto, agente: prev.agent, modelo: prev.model, ...extra } }).catch(() => null)
  : null;
// Estado compartido en mcp-tools: el modelo respondió, se le borran los avisos de límite
await this.helpers.httpRequest({ method: 'POST', url: $env.MCP_URL.replace(/\/mcp\/?$/, '') + '/router/exito', json: true, timeout: 5000,
  headers: { 'X-API-Key': $env.MCP_API_KEY }, body: { modelo: prev.model } }).catch(() => null);

// Algunos modelos de razonamiento devuelven <think>...</think>
const crudo = String($json.output ?? $json.text ?? '');
let output = crudo.replace(/<think>[\s\S]*?<\/think>/g, '').trim();
// Si el modelo dejó toda la respuesta dentro del razonamiento, usar ese texto
if (!output) output = crudo.replace(/<\/?think>/g, '').trim();

// Razonamiento del modelo (si lo devolvió en <think>) y resumen del paso para la web
const pensado = (crudo.match(/<think>([\s\S]*?)<\/think>/) || [])[1];
if (pensado && pensado.trim()) await avisar('razonamiento', pensado.trim().replace(/\s+/g, ' ').slice(0, 600));
if (prev.agent === 'orquestador') {
  let plan = [];
  try { plan = JSON.parse((output.replace(/```(json)?/g, '').match(/\{[\s\S]*\}/) || ['{}'])[0]).plan || []; } catch (e) {}
  await avisar('plan', plan.length ? `Plan: ${plan.map(p => `${p.agente} → ${String(p.tarea).slice(0, 70)}`).join(' · ')}` : 'Plan listo',
    { datos: plan });
} else if (prev.agent === 'verificador') {
  let v = {};
  try { v = JSON.parse((output.replace(/```(json)?/g, '').match(/\{[\s\S]*\}/) || ['{}'])[0]); } catch (e) {}
  const falta = (v.faltantes || []).filter(Boolean);
  await avisar('verificacion', v.cumple === false && falta.length
    ? `Revisión: falta ${falta.join('; ').slice(0, 200)} — se completa`
    : 'Revisión: la respuesta cumple todo lo pedido');
} else {
  await avisar('listo', prev.agent === 'sintesis' ? 'Respuesta integrada' : `${prev.agent} terminó`);
}

return {
  json: {
    agent: prev.agent,
    tarea: prev.prompt,
    model: prev.model,
    proveedor: prev.provider,
    output,
    fallos_previos: prev._router.errors,
    ok: true,
  },
};

// Marca el modelo que falló y devuelve el pedido a "Elegir modelo"
// para que pruebe el siguiente de la lista.
const prev = $('Elegir modelo').item.json;

// Aviso de progreso a la web (solo si el pedido viene de un chat de la web local)
const corto = m => String(m || '').replace(/^(ollama|nvidia)\//, '').replace(/^[\w-]+\/(?=[^/]+$)/, '');
const avisar = (tipo, texto, extra = {}) => prev.session_id
  ? this.helpers.httpRequest({ method: 'POST', url: $env.WEB_EVENTOS_URL, json: true, timeout: 2000,
      headers: { 'X-API-Key': $env.WEB_EVENTOS_TOKEN },
      body: { chat: prev.session_id, tipo, texto, agente: prev.agent, modelo: prev.model, ...extra } }).catch(() => null)
  : null;
const e = $json.error;
const err = e ? String(e.message || e.description || e).slice(0, 500) : 'respuesta vacía del modelo';

// mcp-tools clasifica el error y pone al modelo en pausa (estado compartido entre agentes en paralelo)
const { tipo } = await this.helpers.httpRequest({ method: 'POST', url: $env.MCP_URL.replace(/\/mcp\/?$/, '') + '/router/fallo',
  json: true, timeout: 5000, headers: { 'X-API-Key': $env.MCP_API_KEY }, body: { modelo: prev.model, error: err } })
  .catch(() => ({ tipo: 'otro' }));
const motivo = { limite: 'límite de uso', no_disponible: 'no disponible', caido: 'caído o lento', otro: err.slice(0, 60) }[tipo];
await avisar('fallo', `${corto(prev.model)} falló (${motivo}); probando otro modelo`);

const { model, action, ...rest } = prev;
const r = prev._router;
return {
  json: {
    ...rest,
    _router: {
      ...r,
      tried: [...r.tried, model],
      errors: [...r.errors, { model, tipo, error: err.slice(0, 200) }],
    },
  },
};

const j = $json;
return {
  json: {
    agent: j.agent,
    tarea: j.prompt,
    model: null,
    output: 'No hay modelos NVIDIA disponibles ahora (todos agotados o con error). Probá de nuevo en unos minutos.',
    fallos_previos: j._router.errors,
    ok: false,
  },
};
